begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('e1000000-0000-0000-0000-000000000001','automation-owner@test.invalid'),('e1000000-0000-0000-0000-000000000002','automation-other@test.invalid');
insert into public.tenants(id,name,slug)values('e2000000-0000-0000-0000-000000000001','Automation A','automation-a'),('e2000000-0000-0000-0000-000000000002','Automation B','automation-b');
insert into public.properties(id,tenant_id,name,property_type)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Hotel A','hotel'),('e3000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Hotel B','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','owner'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','owner');
insert into public.guests(id,tenant_id,full_name,phone)values('e4000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Asha','+919111111111');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency,created_at)values('e5000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e4000000-0000-0000-0000-000000000001','confirmed',current_date,current_date+2,5000,'INR',now()-interval '1 day');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('e6000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','12345678001','12345678002','+919999999999','automation-test');
set local role service_role;
select public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[{"provider_id":"group-public","name":"pool_timings","language":"en_US","category":"utility","provider_status":"APPROVED","body":"The swimming pool is open from 7am to 8pm. Please contact reception for help.","parameter_names":[],"supported":true,"service_supported":true,"definition":{"components":[{"type":"BODY","text":"The swimming pool is open from 7am to 8pm. Please contact reception for help."}]}},{"provider_id":"group-private","name":"my_stay","language":"en_US","category":"utility","provider_status":"APPROVED","body":"Hello {{guest_name}}, your personal stay page is {{portal_url}}. Contact reception for help.","parameter_names":["guest_name","portal_url"],"supported":true,"service_supported":true,"definition":{"components":[{"type":"BODY","text":"Hello {{guest_name}}, your personal stay page is {{portal_url}}. Contact reception for help."}]}},{"provider_id":"group-photo","name":"hotel_photo","language":"en_US","category":"utility","provider_status":"APPROVED","body":"Here is our hotel photo. We hope you enjoy your stay.","parameter_names":[],"supported":false,"service_supported":true,"definition":{"components":[{"type":"BODY","text":"Here is our hotel photo. We hope you enjoy your stay."},{"type":"HEADER","format":"IMAGE"},{"type":"BUTTONS","buttons":[{"type":"URL","text":"Location","url":"https://maps.google.com/hotel"}]}]}}]');
reset role;
select set_config('test.group_public',(select id::text from public.message_templates where name='pool_timings'and property_id='e3000000-0000-0000-0000-000000000001'),true);
select set_config('test.group_private',(select id::text from public.message_templates where name='my_stay'and property_id='e3000000-0000-0000-0000-000000000001'),true);
select set_config('test.group_photo',(select id::text from public.message_templates where name='hotel_photo'and property_id='e3000000-0000-0000-0000-000000000001'),true);
insert into public.whatsapp_template_assets values('e3000000-0000-0000-0000-000000000001','group-photo','https://example.com/hotel.jpg');
select set_config('test.group_data',(select jsonb_build_object('intro','Welcome. Choose a category.','items','[{"action":"stay","label":"Stay","enabled":false}]'::jsonb,'maps_url','','review_url','','website_url','','photos','[]'::jsonb,'categories',jsonb_build_array(jsonb_build_object('id','10000000-0000-4000-8000-000000000001','label','Hotel information','enabled',true,'services',(select jsonb_agg(jsonb_build_object('id','20000000-0000-4000-8000-'||lpad(i::text,12,'0'),'label','Service '||i,'enabled',true,'action','reply','template_id',case when i=14 then current_setting('test.group_private')when i=15 then current_setting('test.group_photo')else current_setting('test.group_public')end))from generate_series(1,15)i)))))::text,true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok(format('select public.save_whatsapp_guest_menu(%L::uuid,0,true,%L::jsonb)','e3000000-0000-0000-0000-000000000001',current_setting('test.group_data')),'owner publishes more than ten template-backed services');
select throws_ok(format('select public.save_whatsapp_guest_menu(%L::uuid,0,false,%L::jsonb)','e3000000-0000-0000-0000-000000000002',current_setting('test.group_data')),'42501',null,'cannot publish another hotel menu');
reset role;
select is((select jsonb_array_length(data#>'{categories,0,services}')from public.whatsapp_guest_menu where property_id='e3000000-0000-0000-0000-000000000001'),15,'all fifteen services saved');
select ok((select service_supported and not automation_supported from public.message_templates where id=current_setting('test.group_photo')::uuid),'rich template is service-ready without enabling unsupported event transport');
set local role service_role;
select set_config('test.group_conv',public.ingest_whatsapp_inbound('12345678001','msg:group-hi','919111111111','Asha','group-hi','text','Hi','{}')::text,true);
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'Hi sends grouped root menu');
select is((select body from public.messages where conversation_id=current_setting('test.group_conv')::uuid and direction='out'),'Welcome to Hotel A. How can we help with your stay?','grouped menu greeting includes this hotel name');
select is((select jsonb_array_length(outbound_payload#>'{interactive,action,sections,0,rows}')from public.messages where conversation_id=current_setting('test.group_conv')::uuid and direction='out'),1,'main menu contains category instead of fifteen options');
select public.ingest_whatsapp_inbound('12345678001','msg:group-hi-second','919111111111','Asha','group-hi-second','text','Hello','{}');
select public.ingest_whatsapp_inbound('12345678001','msg:group-hi-third','919111111111','Asha','group-hi-third','text','Menu','{}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),2,'each distinct greeting receives the published menu, even in the same worker tick');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),0,'processed menu greetings are not replayed');
select public.ingest_whatsapp_inbound('12345678001','msg:group-category','919111111111','Asha','group-category','interactive','[interactive]','{"interactive":{"list_reply":{"id":"guest:v:1:category:10000000-0000-4000-8000-000000000001:1","title":"Hotel information"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'category page selection accepted');
select is((select jsonb_array_length(outbound_payload#>'{interactive,action,sections,0,rows}')from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-category')and direction='out'),10,'middle page has seven services plus Previous, More and Main menu');
select public.ingest_whatsapp_inbound('12345678001','msg:group-public','919111111111','Asha','group-public','interactive','[interactive]','{"interactive":{"list_reply":{"id":"guest:v:1:service:20000000-0000-4000-8000-000000000001","title":"Service 1"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'selecting custom service queues assigned template');
select is((select outbound_payload#>>'{template,name}'from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-public')and direction='out'),'pool_timings','correct approved template selected');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),0,'service delivery is deduplicated');
select public.ingest_whatsapp_inbound('12345678001','msg:group-private','919111111111','Asha','group-private','interactive','[interactive]','{"interactive":{"list_reply":{"id":"guest:v:1:service:20000000-0000-4000-8000-000000000014","title":"My stay"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'unverified private service gets safe guidance');
select ok((select body like '%verify your stay%'from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-private')and direction='out'),'custom template cannot leak guest data to an unverified number');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.authorize_whatsapp_stay_updates('e3000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001',0,'granted','Guest identity and number verified at reception.',true);
select public.save_whatsapp_journey('e3000000-0000-0000-0000-000000000001',0,true,1,false,'photo');
reset role;set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:group-verified','919111111111','Asha','group-verified','interactive','[interactive]','{"interactive":{"list_reply":{"id":"guest:v:1:service:20000000-0000-4000-8000-000000000014","title":"My stay"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'verified service renders personal fields');
select ok((select body like 'Hello Asha, your personal stay page is https://guest.test/s/%'from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-verified')and direction='out'),'assigned template gets reservation-specific guest link');
reset role;
select is(private.inbox_delivery_error((select id from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-verified')and direction='out')),null::text,'parameterized service template passes its guarded delivery check');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:group-photo','919111111111','Asha','group-photo','interactive','[interactive]','{"interactive":{"list_reply":{"id":"guest:v:1:service:20000000-0000-4000-8000-000000000015","title":"Hotel photo"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'image-header template queued');
select is((select outbound_payload#>>'{template,components,0,parameters,0,image,link}'from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-photo')and direction='out'),'https://example.com/hotel.jpg','template image parameter uses this hotel’s assigned asset');
reset role;
update public.whatsapp_template_assets set image_url='https://example.com/new.jpg'where property_id='e3000000-0000-0000-0000-000000000001';
select is(private.inbox_delivery_error((select id from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-photo')and direction='out')),'Template delivery image changed.','asset changes invalidate queued old photo');
select is(private.decode_grouped_action('guest:v:0:service:20000000-0000-4000-8000-000000000001',1),'menu','stale version returns current menu rather than wrong service');
select is(private.decode_grouped_action('guest:v:1:service:bad',1),null::text,'forged action IDs rejected');
update public.message_templates set provider_status='REJECTED'where id=current_setting('test.group_public')::uuid;
select is(private.inbox_delivery_error((select id from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='group-public')and direction='out')),'Assigned template changed, expired or lost approval.','approval revocation stops queued service');
select *from finish();rollback;
